const updateProcess = `-- name: UpdateProcess :execrows
UPDATE orchestration.billing_cycle_processes SET
  invoice_id = $2, state = $3, outcome = $4, collection_seq = $5, attempt_id = $6, attempt_status = $7, last_error = $8,
  resume_count = $9, completed_at = $10, version = version + 1, updated_at = $11
WHERE id = $1 AND version = $12
`

type UpdateProcessParams struct {
	ID            uuid.UUID
	InvoiceID     *uuid.UUID
	State         string
	Outcome       *string
	CollectionSeq *int32
	AttemptID     *uuid.UUID
	AttemptStatus *string
	LastError     *string
	ResumeCount   int32
	CompletedAt   *time.Time
	UpdatedAt     time.Time
	Version       int32
}

